import json
from pathlib import Path
A=[]
def add(i,s,q,m,c='material',stage='recognized',**kw):A.append(dict(index=i,classification=c,summary=s,rows=[dict(quote=q,model_quantity=m,stage=stage,issuer_treatment=s,**kw)]))
add(176,'Abernathy à fin juin : 50,1 % non consolidés. Cession effective de toute la participation le 6 juillet 2026 pour environ 530 M$ payable en trois tranches : 250 M$ sous 14 jours, 150 M$ avant fin 2026, environ 130 M$ avant avril 2027. Ne pas compter 530 M$ comme cash déjà reçu ni maintenir l’equity à la date du cutoff. La libération de toute garantie n’est pas explicitée. Justified/Hawesville reste consolidé avec minoritaire doté d’un put ; contradiction de base 1,2 M$/100,588 M$ non résolue.','The sale was effective as of July 6, 2026.','joint_venture_full_disposal_installment_consideration',stage='settled',counterparty='Fluidstack',counterparty_evidence='named',measurement_basis='post_June_July6_50_1percent_sold;530m_payable_not_all_received;guarantee_release_unknown',judgment_sensitive=True)
add(177,'S1 2026 : HPC 52,954 M$ de revenu et 19,246 M$ de profit segment, minage 25,825 M$. Profit segment hors amortissements et frais centraux ; perte de juste valeur warrants de 971,992 M$ non cash. La croissance de revenu HPC ne constitue pas une mesure du cash de service de dette.','HPC leasing segment profit','hpc_segment_profit_not_cash_debt_service',measurement_basis='H1_2026_HPC52_954m_revenue19_246m_segment_profit;excludes_DA_financing')
add(178,'S1 2026 : ATM 196 M$ net, capacité épuisée ; offre d’avril 1,0038 Md$ net contre 1,0357 Md$ brut. Ne pas additionner brut et net ou T2 et S1. Exercices de warrants rapportent 3,7 M$ et 3,4 M$ au S1, sans nouvelle dette LGSA. Aucun rachat d’actions réalisé malgré l’autorisation de 200 M$.','Net proceeds from the offering were approximately $1,003.8 million.','equity_offering_actual_net_cash_proceeds',stage='drawn_or_paid')
add(179,'Juin 2026 : passif warrants Google 1,81669 Md$, perte S1 de réévaluation 972 M$ et T2 de 755,7 M$, non cash. Actifs de trust restreints : 20,1 M$ de titres et 0,5 M$ de cash, indisponibles aux opérations ; la juste valeur n’est pas la liquidité libre. Prix de marché des notes distincts du remboursement nominal.','The Company recognized a loss of $755.7 million and $972.0 million','credit_support_warrant_remeasurement_period_scope',counterparty='Google',counterparty_evidence='named',measurement_basis='H1_2026_972m_loss;not_plus_Q2_755_7m_or_cash_cost',judgment_sensitive=True)
add(180,'Juin 2026 : un bail Fluidstack partiellement commencé ; autres commencements prévus S2 2026/début 2027, 102 MW IT énergisés en juillet. Deux clients HPC sans répartition individuelle publiée. Cash libre 2,619191 Md$ et restreint 409,417 M$ séparés, trust non disponible. Capex non payé 530,594 M$, considération d’acquisition différée 47,065 M$ et conditionnelle 90 M$ distincts du cash dépensé. ARO 16,549 M$ dont 13,1 M$ courant ; coûts de revenu hors D&A.','one of the Fluidstack HPC Leases has partially commenced','customer_lease_partial_commencement',stage='delivered',counterparty='Fluidstack',counterparty_evidence='named',measurement_basis='June2026_partial_commencement;not_all_Fluidstack_leases_active')
add(181,'Juin 2026 : toutes les PSU de cours ont acquis leurs droits, sans preuve de nouveaux contrats commerciaux. RSU restant non acquis : 36,219695 millions en incluant les prestataires. Coûts non reconnus de 286 M$ salariés/administrateurs et 0,8 M$ autres prestataires ; distinguer rémunération non cash, dilution et cash fiscal effectivement payé.','There were no unvested PSUs as of June 30, 2026.','stock_price_awards_vested_not_customer_delivery',c='context')
Path(__file__).with_suffix('.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
M=json.loads(Path('work/continuation398/scope.json').read_text())['rows']
for a in A:
 t=json.loads(Path(M[a['index']]['path']).read_text())['text']
 for r in a['rows']:assert r['quote'] in t,(a['index'],r['quote'])
